// Logo de FATE para los documentos generados.
//
// Va incrustado como PNG en base64 porque jsPDF necesita los bytes de la
// imagen en el momento de dibujar, y pedirlos a la red desde un navegador de
// televisor o con mala señal en el taller es una fuente de fallos que no
// hace falta.

export const LOGO_PDF = 'data:image/png;base64,'

// Proporción ancho / alto, para dibujarlo sin deformar
export const LOGO_PROPORCION = 4.5752

// Isotipo solo, sin la palabra. Casi cuadrado: ocupa poco ancho y se reconoce
// igual a partir de unos 5 mm.
export const ISOTIPO_PDF = 'data:image/png;base64,'
export const ISOTIPO_PROPORCION = 1.4733
